    private val THUMB_SKIP_CANON: Set<String> = setOf(
        "przyprawy dodatki",
    )

    private val NUMBER_REGEX = Regex("""\d+([.,/]\d+)?""")
    private val PUNCT_REGEX = Regex("""[/\-()]""")
    private val WHITESPACE_REGEX = Regex("""\s+""")

    /** Strips quantities/units/size-adjectives down to a bare ingredient name, same regex pipeline as index.html's coreName. */
    fun coreName(label: String): String {
        var s = label.lowercase()
        s = NUMBER_REGEX.replace(s, " ")
        s = PUNCT_REGEX.replace(s, " ")
        var tokens = s.split(WHITESPACE_REGEX).filter { it.isNotEmpty() }
        tokens = tokens.filter { it !in UNIT_WORDS }
        val wIdx = tokens.indexOf("w")
        if (wIdx != -1) tokens = tokens.subList(0, wIdx)
        var result = tokens.joinToString(" ").trim()
        LEMMA_FIX[result]?.let { result = it }
        return result
    }

    /** Maps a coreName() result onto the pantry's canonical key set, or returns it unchanged if there's no known alias. */
    fun pantryCanon(rawCoreName: String): String = RAW_TO_CANON[rawCoreName] ?: rawCoreName

    /** coreName + pantryCanon + a few thumbnail-specific aliases for forms that don't exactly match a pantry key. */
    fun thumbCanon(label: String): String {
        val canon = pantryCanon(coreName(label))
        return THUMB_CANON_ALIASES[canon] ?: canon
    }

    /** FR-35: "$text 🥚" when canon has a known emoji, else text unchanged -- port of index.html's canonEmoji/withEmoji. */
    fun withEmoji(text: String, canon: String): String {
        val emoji = CANON_INFO[canon]?.emoji ?: return text
        return "$text $emoji"
    }

    /**
     * FR-4: the recipe's own biggest (by kcal) ingredient that maps to a known
     * pantry icon, skipping seasonings/condiments unless nothing else qualifies.
     */
    fun mainIngredientInfo(recipe: Recipe): CanonInfo? {
        if (recipe.calc.isEmpty()) return null
        var best: CanonInfo? = null
        var bestKcal = -1
        var fallback: CanonInfo? = null
        var fallbackKcal = -1
        for (item in recipe.calc) {
            val canon = thumbCanon(item.label)
            if (canon in THUMB_SKIP_CANON) continue
            val info = CANON_INFO[canon] ?: continue
            if (item.kcal > fallbackKcal) { fallbackKcal = item.kcal; fallback = info }
            if (info.cat != "Przyprawy" && item.kcal > bestKcal) { bestKcal = item.kcal; best = info }
        }
        return best ?: fallback
    }
